// Get email from webhook safely
const email = $('Webhook').first().json?.body?.data?.buyer?.email;

if (!email || typeof email !== 'string') {
	return [{
		lookup_key: null,
		lookup_error: "Missing or invalid email at body.data.buyer.email"
	}];
}

// Extract domain
const parts = email.split('@');
const domain = parts[1] ? parts[1].trim().toLowerCase() : null;

// If no domain fallback
if (!domain) {
	return [{
		lookup_key: email,  // fallback to whole email
		lookup_error: "Email missing domain — using full email as key"
	}];
}

// List of "generic" consumer email domains
const genericDomains = [
	'gmail.com',
	'yahoo.com',
	'outlook.com',
	'hotmail.com',
	'icloud.com',
	'aol.com',
	'proton.me',
	'me.com'
];

let lookup_key;

// If domain is generic → use full email
if (genericDomains.includes(domain)) {
	lookup_key = email.toLowerCase();   // full email
} else {
	lookup_key = domain;                // just the business domain
}

return [{
	lookup_key,
	message_timestamp: Date.now()
}];

